def build_inclusion_proof(self, index: int) -> dict:
        """Build an RFC 9162 inclusion proof for the record at `index`."""
        if not (0 <= index < len(self._records)):
            raise IndexError(
                f"Index {index} out of range [0, {len(self._records)})"
            )
        leaves = [_digest_bytes(r["chain_hash"]) for r in self._records]
        proof_steps = rfc9162_inclusion_proof(leaves, index)
        root = rfc9162_merkle_root(leaves)
        return {
            "chain_hash": self._records[index]["chain_hash"],
            "proof": proof_steps,
            "merkle_root": "sha256:" + root.hex(),
        }

    def verify_inclusion_proof(self, proof: dict, merkle_root: str) -> bool:
        """Verify an inclusion proof against a given Merkle root.

        merkle_root should be in 'sha256:<hex>' format. If the proof embeds a
        merkle_root field, it must match the supplied root.
        """
        try:
            if "merkle_root" in proof and proof["merkle_root"] != merkle_root:
                return False
            leaf_data = _digest_bytes(proof["chain_hash"])
            root_bytes = _digest_bytes(merkle_root)
            return rfc9162_verify_inclusion(leaf_data, proof["proof"], root_bytes)
        except (KeyError, ValueError, TypeError):
            return False

@property
    def records(self) -> list[dict]:
        """Read-only access to the record list (deep copy)."""
        return copy.deepcopy(self._records)

    @property
    def epochs(self) -> list[dict]:
        """Read-only access to the epoch list (deep copy)."""
        return copy.deepcopy(self._epochs)

    @classmethod
    def load_json(cls, path: str) -> "VerificationChain":
        """Deserialize a chain from a JSON file.

        Preserves the schema_version from the loaded file to prevent
        silent version downgrades on round-trip.

        Validates basic structure: records and epochs must be lists,
        and each record must contain the required keys.
        """
        _REQUIRED_RECORD_KEYS = {
            "sealed_body", "entry_hash", "prev_hash", "chain_hash",
        }
        with open(path, "r") as f:
            data = json.load(f)
        records = data.get("records", [])
        epochs = data.get("epochs", [])
        if not isinstance(records, list):
            raise ValueError("'records' must be a list")
        if not isinstance(epochs, list):
            raise ValueError("'epochs' must be a list")
        # E31-18 fix: validate each epoch is a dict. Without this,
        # non-dict epochs (strings, ints, null) pass load but crash
        # verify_chain() with AttributeError on epoch.get() — and
        # AttributeError is not in the except clause there.
        for i, ep in enumerate(epochs):
            if not isinstance(ep, dict):
                raise ValueError(f"Epoch {i} is not a dict")
        for i, rec in enumerate(records):
            if not isinstance(rec, dict):
                raise ValueError(f"Record {i} is not a dict")
            missing = _REQUIRED_RECORD_KEYS - rec.keys()
            if missing:
                raise ValueError(
                    f"Record {i} missing required keys: {missing}"
                )
        chain = cls()
        chain._schema_version = data.get("schema_version", SCHEMA_VERSION)
